/**
 * @event
 * @name scwin.grd_resultList_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_resultList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_resultList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_resultList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (columnId === "__rowAct") { if (r["stdCdGrntFeeProcsStatCd"] === '2' && r["stdCdGrntFeeProcsStatCd"] !== '' && (r["applProcsTpCd"] === '0' || r["applProcsTpCd"] === '3')) { if (typeof scwin.print === 'function') { await scwin.print(r["isuNm"], r["stdCdApplContnTpNm"], r["applDate"], r["stdCdGrntFee"], r["asumAcntNoFmtHyp"]); } else { console.error('[sdd] 행 동작 미정의: scwin.print (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.print'); } return; } return; } if (r["stdCdProcsTpCd"] === '1') { if (typeof scwin.popupCode3 === 'function') { scwin.popupCode3(r["stdCdApplContnTpCd"], r["stdCdApplId"], r["cpBndTpCd"]); } else { console.error('[sdd] 행 동작 미정의: scwin.popupCode3 (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.popupCode3'); } return; }
        if (r["applProcsTpCd"] === '2' && r["stdCdApplContnTpCd"] !== '08' && r["stdCdProcsTpCd"] === '1' && r["retApplId"] === '') { if (typeof scwin.returnAppl === 'function') { await scwin.returnAppl(r["stdCdApplContnTpCd"], r["stdCdApplId"], r["cpBndTpCd"], r["retRsn"], r["asumAcntNo"], r["stdCdGrntFeeProcsStatCd"]); } else { console.error('[sdd] 행 동작 미정의: scwin.returnAppl (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.returnAppl'); } return; }
        if (typeof scwin.popupCode2 === 'function') { scwin.popupCode2(r["stdCdApplContnTpCd"], r["stdCd"], r["cpBndTpCd"]); } else { console.error('[sdd] 행 동작 미정의: scwin.popupCode2 (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.popupCode2'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_resultList.oncellclick' });
    }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_search = async function () {
    const sbmOptions = {
        id: "tx_fn_search",
        method: "post",
        action: "/stdcd/stdcdNewReqList.do?method=stdcdNewReqList&pageDiv=",
        ref: "dma_searchReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldinf15000.tx_fn_search" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_print
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_print = async function () {
    try { return await $c.data.downFile("/common/newPrint.do", "", ($c.util.getComponent("dma_printReq") ? $c.util.getComponent("dma_printReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name scwin.tx_load_list
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/stdcd/stdcdNewReqList.do?method=stdcdNewReqList&pageDiv=",
        ref: "dma_loadListReq",
        target: "dlt_applProcsTpCdList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldinf15000.tx_load_list" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    const rj = res && res.responseJSON;
    const tot = rj && (rj["total"] != null ? rj["total"] : (rj.body && rj.body["total"]));
    if (tot != null && tot !== "") {
        $c.util.getComponent("krxpage_pagenavigator_216").setCount(Math.ceil(Number(tot) / 10));
    }
    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

// 표준 API 조합으로 새로 작성한 검사 함수
/**
 * @method
 * @name scwin.appDate2
 * @author Inswave
 * @date 2026. 09. 29
